          "@type": "Question",
          "name": "Is a facade mock-up always required?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Not always. Small, simple projects may use samples only. Large, tall or complex facades usually need a full mock-up."
          }
        },
        {
          "@type": "Question",
          "name": "Who pays for the mock-up?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "This depends on the contract. Check that your quote states whether the mock-up and testing are included."
          }
        },
        {
          "@type": "Question",
          "name": "How long does a mock-up take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It depends on the size and complexity of the system. Ask your supplier for a schedule that includes review time."
          }
        },
        {
          "@type": "Question",
          "name": "Can the approved mock-up be used on the building?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sometimes it is kept as a reference or reused if allowed. Agree this early."
          }
        },
        {
          "@type": "Question",
          "name": "What if the mock-up fails a test?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The design or detail is changed, the mock-up is rebuilt or modified and re-tested before production starts. That is exactly why you build one."
          }
        }
